CREATE POLICY "banks_admin_all" ON public.banks
    FOR ALL TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));

CREATE POLICY "banks_select_authenticated" ON public.banks
    FOR SELECT TO authenticated
    USING ((is_active = true));

CREATE POLICY "case_follow_ups_select" ON public.case_follow_ups
    FOR SELECT TO authenticated
    USING ((is_admin_user() OR (EXISTS ( SELECT 1
   FROM cases c
  WHERE ((c.id = case_follow_ups.case_id) AND (c.created_by = auth.uid()))))));

CREATE POLICY "cases_delete" ON public.cases
    FOR DELETE TO authenticated
    USING (((created_by = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text])))))));

CREATE POLICY "cases_insert" ON public.cases
    FOR INSERT TO authenticated
    WITH CHECK ((created_by = auth.uid()));

CREATE POLICY "cases_select" ON public.cases
    FOR SELECT TO authenticated
    USING (((created_by = auth.uid()) OR is_admin_user()));

CREATE POLICY "cases_update" ON public.cases
    FOR UPDATE TO authenticated
    USING (((created_by = auth.uid()) OR is_admin_user()))
    WITH CHECK (((created_by = auth.uid()) OR is_admin_user()));

CREATE POLICY "commission_payouts_select" ON public.commission_payouts
    FOR SELECT TO authenticated
    USING ((is_admin_user() OR (EXISTS ( SELECT 1
   FROM cases c
  WHERE ((c.id = commission_payouts.case_id) AND (c.created_by = auth.uid()))))));

CREATE POLICY "payslip_company_settings_admin_all" ON public.payslip_company_settings
    FOR ALL TO authenticated
    USING (is_admin_user())
    WITH CHECK (is_admin_user());

CREATE POLICY "payslip_employees_admin_all" ON public.payslip_employees
    FOR ALL TO authenticated
    USING (is_admin_user())
    WITH CHECK (is_admin_user());

CREATE POLICY "payslip_items_admin_all" ON public.payslip_items
    FOR ALL TO authenticated
    USING (is_admin_user())
    WITH CHECK (is_admin_user());

CREATE POLICY "payslip_records_admin_all" ON public.payslip_records
    FOR ALL TO authenticated
    USING (is_admin_user())
    WITH CHECK (is_admin_user());

CREATE POLICY "Users can read own profile" ON public.profiles
    FOR SELECT TO public
    USING ((auth.uid() = id));

CREATE POLICY "Users can update own profile" ON public.profiles
    FOR UPDATE TO public
    USING ((auth.uid() = id));

CREATE POLICY "profiles_admin_select" ON public.profiles
    FOR SELECT TO authenticated
    USING (is_admin_user());

CREATE POLICY "Admins can view all calendar events" ON public.property_calendar_events
    FOR SELECT TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));

CREATE POLICY "Agents can view own calendar events" ON public.property_calendar_events
    FOR SELECT TO authenticated
    USING ((agent_id = auth.uid()));

CREATE POLICY "logs_select" ON public.property_case_activity_logs
    FOR SELECT TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM property_cases pc
  WHERE ((pc.id = property_case_activity_logs.case_id) AND ((pc.agent_id = auth.uid()) OR (EXISTS ( SELECT 1
           FROM profiles
          WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))))))));

CREATE POLICY "docs_admin_delete" ON public.property_case_documents
    FOR DELETE TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));

CREATE POLICY "docs_insert" ON public.property_case_documents
    FOR INSERT TO authenticated
    WITH CHECK (((uploaded_by = auth.uid()) AND (EXISTS ( SELECT 1
   FROM property_cases pc
  WHERE ((pc.id = property_case_documents.case_id) AND (pc.agent_id = auth.uid()))))));

CREATE POLICY "docs_select" ON public.property_case_documents
    FOR SELECT TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM property_cases pc
  WHERE ((pc.id = property_case_documents.case_id) AND ((pc.agent_id = auth.uid()) OR (EXISTS ( SELECT 1
           FROM profiles
          WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))))))));

CREATE POLICY "pc_delete" ON public.property_cases
    FOR DELETE TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));

CREATE POLICY "pc_select" ON public.property_cases
    FOR SELECT TO authenticated
    USING (((agent_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text])))))));

CREATE POLICY "reminders_select" ON public.property_reminders
    FOR SELECT TO authenticated
    USING ((EXISTS ( SELECT 1
   FROM property_cases pc
  WHERE ((pc.id = property_reminders.case_id) AND ((pc.agent_id = auth.uid()) OR (EXISTS ( SELECT 1
           FROM profiles
          WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))))))));

CREATE POLICY "user_consents_admin_read" ON public.user_consents
    FOR SELECT TO public
    USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));

CREATE POLICY "user_consents_self_insert" ON public.user_consents
    FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "user_consents_self_read" ON public.user_consents
    FOR SELECT TO public
    USING ((auth.uid() = user_id));
